<?php
declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_once dirname(__DIR__,2).'/includes/alert-engine.php';header('Content-Type: application/json; charset=utf-8');
function p4_action_reply(int $s,array $b):never{http_response_code($s);echo json_encode($b,JSON_THROW_ON_ERROR);exit;}if(($_SERVER['REQUEST_METHOD']??'')!=='POST')p4_action_reply(405,['success'=>false,'message'=>'Use POST.']);$u=current_user();if(!$u)p4_action_reply(401,['success'=>false,'message'=>'Authentication required.']);if($u['role_slug']!=='administrator')p4_action_reply(403,['success'=>false,'message'=>'Administrator access is required.']);$body=json_decode(file_get_contents('php://input'),true);if(!is_array($body))p4_action_reply(400,['success'=>false,'message'=>'Send a JSON object.']);if(!isset($body['csrf_token'])||!hash_equals($_SESSION['csrf_token']??'',(string)$body['csrf_token']))p4_action_reply(403,['success'=>false,'message'=>'Invalid CSRF token.']);$id=filter_var($body['alert_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$id)p4_action_reply(422,['success'=>false,'message'=>'Select an alert.']);try{if(($body['action']??'')==='acknowledge')phase4_acknowledge_alert((int)$id,(int)$u['id']);elseif(($body['action']??'')==='resolve')phase4_resolve_alert((int)$id,(int)$u['id'],(string)($body['resolution_note']??''));else p4_action_reply(422,['success'=>false,'message'=>'Unsupported action.']);p4_action_reply(200,['success'=>true]);}catch(InvalidArgumentException $e){p4_action_reply(409,['success'=>false,'message'=>$e->getMessage()]);}
